{"hypotheses": [
  {
    "root_cause": "1",
    "mechanism": "A recent code or configuration change introduced a bug in demand parsing/validation/transform logic.",
    "statement": "The failure originates inside the ingestion service’s own demand-processing path."
  },
  {
    "root_cause": "2",
    "mechanism": "The upstream demand feed began sending malformed, schema-incompatible, or truncated records at the incident start.",
    "statement": "Ingestion fails because inbound demand data violates the service’s expected format."
  },
  {
    "root_cause": "3",
    "mechanism": "The persistent store or message bus that receives ingested demand became unavailable or too slow, causing write failures.",
    "statement": "Ingestion reports demand errors because it cannot successfully write or forward records."
  },
  {
    "root_cause": "4",
    "mechanism": "An expired or rotated credential or token caused authentication or authorization failure on a source or sink connection.",
    "statement": "Demand ingestion fails at an external API or database boundary due to auth, not demand content."
  },
  {
    "root_cause": "5",
    "mechanism": "CPU, memory, thread-pool, or connection-pool exhaustion caused demand ingestion threads to fail or stall.",
    "statement": "The ingestion service lacked capacity during the incident window, producing demand ingestion errors."
  }
]}
